INSERT INTO weenie_properties_emote (object_Id, category, probability, weenie_Class_Id, quest) VALUES (900324, 7, 1.0, NULL, NULL);
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent) VALUES (@e, 0, 12, 0, 1);
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) VALUES (@e, 1, 21, 0, 1, 'EmpyreanVaultAttuned');
INSERT INTO weenie_properties_emote (object_Id, category, probability, weenie_Class_Id, quest) VALUES (900324, 12, 1.0, NULL, 'EmpyreanVaultAttuned');
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) VALUES (@e, 0, 10, 1, 1, 'The Forge Gate knows you now. Go down through the vault and end the Warden before the Hopeslayer''s shadow reaches its forge.');
INSERT INTO weenie_properties_emote (object_Id, category, probability, weenie_Class_Id, quest) VALUES (900324, 13, 1.0, NULL, 'EmpyreanVaultAttuned');
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) VALUES (@e, 0, 10, 1, 1, 'A remnant of the Soul Crystal was carried into the deep earth, and it woke the vault below us. Its guardian, the Forge-Warden, was bound to destroy anything touched by Shadow, and now it destroys everything.');
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) VALUES (@e, 1, 10, 1, 1, 'The golems that walk out of that door carry aetherium cores. Bring me three and I will attune you to the Forge Gate at the bottom of the vault. The cracked cores also open the vault''s first seal.');
INSERT INTO weenie_properties_emote (object_Id, category, probability, weenie_Class_Id, quest) VALUES (900324, 6, 1.0, 900301, NULL);
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent) VALUES (@e, 0, 12, 0, 1);
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) VALUES (@e, 1, 21, 0, 1, 'EmpyreanVaultAttuned@Core');
INSERT INTO weenie_properties_emote (object_Id, category, probability, weenie_Class_Id, quest) VALUES (900324, 12, 1.0, NULL, 'EmpyreanVaultAttuned@Core');
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) VALUES (@e, 0, 10, 1, 1, 'The Forge Gate knows you now. Go down through the vault and end the Warden before the Hopeslayer''s shadow reaches its forge.');
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, weenie_Class_Id, stack_Size) VALUES (@e, 1, 3, 0, 1, 900301, 1);
INSERT INTO weenie_properties_emote (object_Id, category, probability, weenie_Class_Id, quest) VALUES (900324, 13, 1.0, NULL, 'EmpyreanVaultAttuned@Core');
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message, min, max) VALUES (@e, 0, 30, 0, 1, 'EmpyreanVaultCoresGiven', 2, 999);
INSERT INTO weenie_properties_emote (object_Id, category, probability, weenie_Class_Id, quest) VALUES (900324, 12, 1.0, NULL, 'EmpyreanVaultCoresGiven');
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) VALUES (@e, 0, 10, 1, 1, 'Three cores. Hold still while I bind their song to you.');
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) VALUES (@e, 1, 31, 0, 1, 'EmpyreanVaultCoresGiven');
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) VALUES (@e, 2, 22, 0, 1, 'EmpyreanVaultAttuned');
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, percent, min_64, max_64) VALUES (@e, 3, 49, 0, 1, 0.1, 0, 50000000);
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, amount) VALUES (@e, 4, 34, 0, 1, 472);
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) VALUES (@e, 5, 10, 1, 1, 'It is done. The Forge Gate will open for you. May Asheron''s light go with you into the dark.');
INSERT INTO weenie_properties_emote (object_Id, category, probability, weenie_Class_Id, quest) VALUES (900324, 13, 1.0, NULL, 'EmpyreanVaultCoresGiven');
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message, amount) VALUES (@e, 0, 33, 0, 1, 'EmpyreanVaultCoresGiven', 1);
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) VALUES (@e, 1, 10, 1, 1, 'Good. The core still sings. Bring me more; three are needed to attune you.');
